import java.util.Scanner;

public class Main {
    static final int N = 1000500;
    static final long mod = 1000000007;
    static long[] cycle_lengths = new long[N];
    static boolean[] visited_nodes = new boolean[N];
    static long[] combined = new long[N];

    static long compute_cycle_length(long start, long k, long n) {
        long count = 0;
        while (true) {
            if (visited_nodes[(int) start]) break;
            visited_nodes[(int) start] = true;
            start = (start * k) % n;
            count++;
        }
        return count;
    }

    static long binary_exponentiation(long base, long exponent) {
        if (exponent == 0) return 1;
        long temp = binary_exponentiation(base, exponent / 2);
        if (exponent % 2 == 0) {
            return (temp * temp) % mod;
        } else {
            return (base * ((temp * temp) % mod)) % mod;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long k = sc.nextLong();

        if (k == 0) {
            System.out.println(binary_exponentiation(n, n - 1));
            sc.close();
            return;
        }

        for (long i = 0; i < n; i++) {
            if (!visited_nodes[(int) i]) {
                long cycle_len = compute_cycle_length(i, k, n);
                cycle_lengths[(int) cycle_len]++;
            }
        }

        for (long i = 1; i <= n; i++) {
            for (long j = i; j <= n; j += i) {
                if (cycle_lengths[(int) j] != 0) {
                    combined[(int) j] += cycle_lengths[(int) i] * i;
                }
            }
        }

        long answer = 1;
        for (long i = 1; i <= n; i++) {
            if (combined[(int) i] != 0) {
                answer = (answer * binary_exponentiation(combined[(int) i], cycle_lengths[(int) i])) % mod;
            }
        }

        System.out.println(answer);
        sc.close();
    }
}
